edge_case_tests.assertion_pseudocode:
import inspect
from af_sdk import spec_read, context_search, context_get, memory_recall, subtask_state
for fn in [spec_read, context_search, context_get, memory_recall, subtask_state]:
    hints = get_type_hints(fn)
    sig = inspect.signature(fn)
    for param_name, param in sig.parameters.items():
        if param_name == 'self':
            continue
        assert param_name in hints, f'{fn.__name__}.{param_name} missing type annotation'
    assert 'return' in hints, f'{fn.__name__} missing return type annotation'
